    let n01 = hash(ix, iy + 1);
    let n11 = hash(ix + 1, iy + 1);

    let nx0 = n00 + (n10 - n00) * ux;
    let nx1 = n01 + (n11 - n01) * ux;
    return nx0 + (nx1 - nx0) * uy;
